def suggestions(words: list[str], typed: str) -> list[list[str]]:
    root = {"kids": {}, "top": []}
    for w in sorted(set(words)):
        node = root
        for ch in w:
            node = node["kids"].setdefault(ch, {"kids": {}, "top": []})
            if len(node["top"]) < 3:
                node["top"].append(w)
    res, node = [], root
    for ch in typed:
        node = node["kids"].get(ch) if node is not None else None
        res.append(node["top"] if node is not None else [])
    return res
